 1→//! Lint output formatters.
 2→//!
 3→//! This module provides formatters for outputting lint diagnostics
 4→//! in different formats (human-readable, JSON, SARIF).
 5→
 6→pub mod human;
 7→pub mod json;
 8→pub mod sarif;
 9→
10→use crate::lint::LintDiagnostic;
11→use std::io::Write;
12→
13→/// Output format for lint results.
14→#[derive(Debug, Clone, Copy, PartialEq, Eq)]
15→pub enum OutputFormat {
16→    Human,
17→    Json,
18→    Sarif,
19→}
20→
21→/// Trait for formatting lint output.
22→pub trait LintFormatter {
23→    /// Format diagnostics to the given writer.
24→    fn format<W: Write>(
25→        &self,
26→        diagnostics: &[LintDiagnostic],
27→        writer: &mut W,
28→    ) -> std::io::Result<()>;
29→}
30→
31→pub use human::HumanFormatter;
32→pub use json::JsonFormatter;
33→pub use sarif::SarifFormatter;
