  1→//! JSON output formatter.
  2→//!
  3→//! Formats lint diagnostics as machine-readable JSON for tooling integration.
  4→
  5→use super::LintFormatter;
  6→use crate::lint::{LintDiagnostic, Severity};
  7→use serde::Serialize;
  8→use std::io::Write;
  9→
 10→/// Formats lint output as JSON.
 11→pub struct JsonFormatter;
 12→
 13→#[derive(Serialize)]
 14→struct JsonOutput {
 15→    diagnostics: Vec<JsonDiagnostic>,
 16→    summary: JsonSummary,
 17→}
 18→
 19→#[derive(Serialize)]
 20→struct JsonDiagnostic {
 21→    rule_id: String,
 22→    severity: String,
 23→    message: String,
 24→    #[serde(skip_serializing_if = "Option::is_none")]
 25→    file: Option<String>,
 26→    #[serde(skip_serializing_if = "Option::is_none")]
 27→    line: Option<usize>,
 28→    #[serde(skip_serializing_if = "Option::is_none")]
 29→    column: Option<usize>,
 30→    #[serde(skip_serializing_if = "Option::is_none")]
 31→    suggestion: Option<String>,
 32→}
 33→
 34→#[derive(Serialize)]
 35→struct JsonSummary {
 36→    total: usize,
 37→    errors: usize,
 38→    warnings: usize,
 39→    hints: usize,
 40→}
 41→
 42→impl JsonFormatter {
 43→    /// Create a new JSON formatter.
 44→    pub fn new() -> Self {
 45→        Self
 46→    }
 47→
 48→    fn severity_to_string(severity: Severity) -> &'static str {
 49→        match severity {
 50→            Severity::Hint => "hint",
 51→            Severity::Warning => "warning",
 52→            Severity::Error => "error",
 53→        }
 54→    }
 55→}
 56→
 57→impl Default for JsonFormatter {
 58→    fn default() -> Self {
 59→        Self::new()
 60→    }
 61→}
 62→
 63→impl LintFormatter for JsonFormatter {
 64→    fn format<W: Write>(
 65→        &self,
 66→        diagnostics: &[LintDiagnostic],
 67→        writer: &mut W,
 68→    ) -> std::io::Result<()> {
 69→        let json_diagnostics: Vec<_> = diagnostics
 70→            .iter()
 71→            .map(|d| JsonDiagnostic {
 72→                rule_id: d.rule_id.0.clone(),
 73→                severity: Self::severity_to_string(d.severity).to_string(),
 74→                message: d.message.clone(),
 75→                file: d.span.as_ref().map(|s| s.file.display().to_string()),
 76→                line: d.span.as_ref().map(|s| s.start_line),
 77→                column: d.span.as_ref().map(|s| s.start_col),
 78→                suggestion: d.suggestion.clone(),
 79→            })
 80→            .collect();
 81→
 82→        let summary = JsonSummary {
 83→            total: diagnostics.len(),
 84→            errors: diagnostics
 85→                .iter()
 86→                .filter(|d| d.severity == Severity::Error)
 87→                .count(),
 88→            warnings: diagnostics
 89→                .iter()
 90→                .filter(|d| d.severity == Severity::Warning)
 91→                .count(),
 92→            hints: diagnostics
 93→                .iter()
 94→                .filter(|d| d.severity == Severity::Hint)
 95→                .count(),
 96→        };
 97→
 98→        let output = JsonOutput {
 99→            diagnostics: json_diagnostics,
100→            summary,
101→        };
102→
103→        serde_json::to_writer_pretty(writer, &output).map_err(std::io::Error::other)?;
104→
105→        Ok(())
106→    }
107→}
108→
109→#[cfg(test)]
110→mod tests {
111→    use super::*;
112→    use crate::lint::{RuleId, Span};
113→
114→    #[test]
115→    fn produces_valid_json() {
116→        let formatter = JsonFormatter::new();
117→        let diagnostics = vec![LintDiagnostic::new(
118→            RuleId::new("test"),
119→            Severity::Error,
120→            "Error message",
121→        )];
122→
123→        let mut output = Vec::new();
124→        formatter.format(&diagnostics, &mut output).unwrap();
125→
126→        let parsed: serde_json::Value = serde_json::from_slice(&output).unwrap();
127→        assert!(parsed["diagnostics"].is_array());
128→        assert_eq!(parsed["summary"]["total"].as_u64().unwrap(), 1);
129→    }
130→
131→    #[test]
132→    fn includes_location_when_present() {
133→        let formatter = JsonFormatter::new();
134→        let diagnostics =
135→            vec![
136→                LintDiagnostic::new(RuleId::new("test"), Severity::Error, "msg")
137→                    .with_span(Span::new("config.yml", 10, 5, 10, 20)),
138→            ];
139→
140→        let mut output = Vec::new();
141→        formatter.format(&diagnostics, &mut output).unwrap();
142→
143→        let parsed: serde_json::Value = serde_json::from_slice(&output).unwrap();
144→        assert_eq!(parsed["diagnostics"][0]["line"], 10);
145→        assert_eq!(parsed["diagnostics"][0]["column"], 5);
146→    }
147→
148→    #[test]
149→    fn omits_location_when_absent() {
150→        let formatter = JsonFormatter::new();
151→        let diagnostics = vec![LintDiagnostic::new(
152→            RuleId::new("test"),
153→            Severity::Error,
154→            "msg",
155→        )];
156→
157→        let mut output = Vec::new();
158→        formatter.format(&diagnostics, &mut output).unwrap();
159→
160→        let parsed: serde_json::Value = serde_json::from_slice(&output).unwrap();
161→        assert!(parsed["diagnostics"][0]["line"].is_null());
162→    }
163→
164→    #[test]
165→    fn summary_counts_by_severity() {
166→        let formatter = JsonFormatter::new();
167→        let diagnostics = vec![
168→            LintDiagnostic::new(RuleId::new("r1"), Severity::Error, "e1"),
169→            LintDiagnostic::new(RuleId::new("r2"), Severity::Error, "e2"),
170→            LintDiagnostic::new(RuleId::new("r3"), Severity::Warning, "w1"),
171→            LintDiagnostic::new(RuleId::new("r4"), Severity::Hint, "h1"),
172→        ];
173→
174→        let mut output = Vec::new();
175→        formatter.format(&diagnostics, &mut output).unwrap();
176→
177→        let parsed: serde_json::Value = serde_json::from_slice(&output).unwrap();
178→        assert_eq!(parsed["summary"]["total"], 4);
179→        assert_eq!(parsed["summary"]["errors"], 2);
180→        assert_eq!(parsed["summary"]["warnings"], 1);
181→        assert_eq!(parsed["summary"]["hints"], 1);
182→    }
183→
184→    #[test]
185→    fn default_impl_works() {
186→        let formatter = JsonFormatter;
187→        let diagnostics: Vec<LintDiagnostic> = vec![];
188→
189→        let mut output = Vec::new();
190→        formatter.format(&diagnostics, &mut output).unwrap();
191→
192→        let parsed: serde_json::Value = serde_json::from_slice(&output).unwrap();
193→        assert_eq!(parsed["summary"]["total"], 0);
194→    }
195→}
