  1→//! Status command implementation.
  2→//!
  3→//! The `bivvy status` command shows current setup status.
  4→
  5→use std::collections::HashSet;
  6→use std::path::{Path, PathBuf};
  7→use std::time::Duration;
  8→
  9→use crate::cli::args::StatusArgs;
 10→use crate::config::load_merged_config;
 11→use crate::environment::resolver::ResolvedEnvironment;
 12→use crate::error::{BivvyError, Result};
 13→use crate::requirements::checker::GapChecker;
 14→use crate::requirements::probe::EnvironmentProbe;
 15→use crate::requirements::registry::RequirementRegistry;
 16→use crate::requirements::status::RequirementStatus;
 17→use crate::state::{ProjectId, StateStore, StepStatus};
 18→use crate::ui::theme::BivvyTheme;
 19→use crate::ui::{format_relative_time, hints, OutputMode, StatusKind, UserInterface};
 20→
 21→use super::dispatcher::{Command, CommandResult};
 22→
 23→/// The status command implementation.
 24→pub struct StatusCommand {
 25→    project_root: PathBuf,
 26→    args: StatusArgs,
 27→}
 28→
 29→impl StatusCommand {
 30→    /// Create a new status command.
 31→    pub fn new(project_root: &Path, args: StatusArgs) -> Self {
 32→        Self {
 33→            project_root: project_root.to_path_buf(),
 34→            args,
 35→        }
 36→    }
 37→
 38→    /// Get the project root path.
 39→    pub fn project_root(&self) -> &Path {
 40→        &self.project_root
 41→    }
 42→
 43→    /// Get the command arguments.
 44→    pub fn args(&self) -> &StatusArgs {
 45→        &self.args
 46→    }
 47→
 48→    /// Resolve the target environment using the priority chain.
 49→    fn resolve_environment(&self, config: &crate::config::BivvyConfig) -> ResolvedEnvironment {
 50→        ResolvedEnvironment::resolve_from_config(self.args.env.as_deref(), &config.settings)
 51→    }
 52→}
 53→
 54→impl Command for StatusCommand {
 55→    fn execute(&self, ui: &mut dyn UserInterface) -> Result<CommandResult> {
 56→        // Load configuration
 57→        let config = match load_merged_config(&self.project_root) {
 58→            Ok(c) => c,
 59→            Err(BivvyError::ConfigNotFound { .. }) => {
 60→                ui.error("No configuration found. Run 'bivvy init' first.");
 61→                return Ok(CommandResult::failure(2));
 62→            }
 63→            Err(e) => return Err(e),
 64→        };
 65→
 66→        // Apply config default_output when no CLI flag was explicitly set
 67→        if ui.output_mode() == OutputMode::Normal {
 68→            ui.set_output_mode(config.settings.default_output.into());
 69→        }
 70→
 71→        // Get project identity
 72→        let project_id = ProjectId::from_path(&self.project_root)?;
 73→
 74→        // Load state
 75→        let state = StateStore::load(&project_id)?;
 76→
 77→        let theme = BivvyTheme::new();
 78→
 79→        // Resolve environment
 80→        let resolved_env = self.resolve_environment(&config);
 81→
 82→        // Show header: ⛺ AppName — Status
 83→        let app_name = config.app_name.as_deref().unwrap_or("Bivvy Setup");
 84→        ui.message(&format!(
 85→            "\n  {} {} {} {}\n",
 86→            theme.header.apply_to("⛺"),
 87→            theme.highlight.apply_to(app_name),
 88→            theme.dim.apply_to("—"),
 89→            theme.dim.apply_to("Status"),
 90→        ));
 91→
 92→        // Show environment info
 93→        ui.message(&format!(
 94→            "  {} {} ({})",
 95→            theme.key.apply_to("Environment:"),
 96→            theme.highlight.apply_to(&resolved_env.name),
 97→            theme.dim.apply_to(resolved_env.source.to_string()),
 98→        ));
 99→        ui.message("");
100→
101→        // Show last run info with relative time
102→        if let Some(last_run) = state.last_run_record() {
103→            ui.message(&format!(
104→                "  {} {} {} {}",
105→                theme.key.apply_to("Last run:"),
106→                theme.dim.apply_to(format_relative_time(last_run.timestamp)),
107→                theme.dim.apply_to("·"),
108→                theme
109→                    .dim
110→                    .apply_to(format!("{} workflow", last_run.workflow)),
111→            ));
112→            ui.message("");
113→        }
114→
115→        // Show step status
116→        ui.message(&format!("  {}", theme.key.apply_to("Steps:")));
117→
118→        let step_names: Vec<&String> = if let Some(ref step_name) = self.args.step {
119→            if config.steps.contains_key(step_name) {
120→                vec![step_name]
121→            } else {
122→                ui.error(&format!("Unknown step: {}", step_name));
123→                return Ok(CommandResult::failure(1));
124→            }
125→        } else {
126→            config.steps.keys().collect()
127→        };
128→
129→        for step_name in &step_names {
130→            // Check if step is skipped by only_environments
131→            let step_config = config.steps.get(*step_name);
132→            let skipped = step_config
133→                .map(|s| {
134→                    !s.only_environments.is_empty()
135→                        && !s.only_environments.iter().any(|e| e == &resolved_env.name)
136→                })
137→                .unwrap_or(false);
138→
139→            if skipped {
140→                ui.message(&format!(
141→                    "    {} {:<20} {}",
142→                    theme.dim.apply_to("⊘"),
143→                    step_name,
144→                    theme
145→                        .dim
146→                        .apply_to(format!("(skipped in {})", resolved_env.name)),
147→                ));
148→                continue;
149→            }
150→

  1→//! Lint rule definitions.
  2→//!
  3→//! This module provides the core traits and types for defining lint rules:
  4→//!
  5→//! - [`LintRule`] - The trait that all lint rules must implement
  6→//! - [`RuleId`] - Unique identifier for a lint rule
  7→//! - [`Severity`] - Severity level for diagnostics (Hint, Warning, Error)
  8→
  9→use super::diagnostic::LintDiagnostic;
 10→use crate::config::BivvyConfig;
 11→
 12→/// Unique identifier for a lint rule.
 13→#[derive(Debug, Clone, PartialEq, Eq, Hash)]
 14→pub struct RuleId(pub String);
 15→
 16→impl RuleId {
 17→    /// Create a new rule ID.
 18→    pub fn new(id: impl Into<String>) -> Self {
 19→        Self(id.into())
 20→    }
 21→}
 22→
 23→impl std::fmt::Display for RuleId {
 24→    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
 25→        write!(f, "{}", self.0)
 26→    }
 27→}
 28→
 29→/// Severity level for lint diagnostics.
 30→#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
 31→pub enum Severity {
 32→    /// Informational hint, does not affect validity.
 33→    Hint,
 34→    /// Warning that should be addressed.
 35→    Warning,
 36→    /// Error that prevents execution.
 37→    Error,
 38→}
 39→
 40→impl std::fmt::Display for Severity {
 41→    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
 42→        match self {
 43→            Severity::Hint => write!(f, "hint"),
 44→            Severity::Warning => write!(f, "warning"),
 45→            Severity::Error => write!(f, "error"),
 46→        }
 47→    }
 48→}
 49→
 50→/// A lint rule that validates configuration.
 51→///
 52→/// Lint rules are the primary mechanism for configuration validation.
 53→/// Each rule checks for a specific issue and produces diagnostics
 54→/// when problems are found.
 55→pub trait LintRule: Send + Sync {
 56→    /// Unique identifier for this rule.
 57→    fn id(&self) -> RuleId;
 58→
 59→    /// Human-readable name of the rule.
 60→    fn name(&self) -> &str;
 61→
 62→    /// Description of what this rule checks.
 63→    fn description(&self) -> &str;
 64→
 65→    /// Default severity for this rule.
 66→    fn default_severity(&self) -> Severity;
 67→
 68→    /// Check the configuration and return any diagnostics.
 69→    fn check(&self, config: &BivvyConfig) -> Vec<LintDiagnostic>;
 70→
 71→    /// Whether this rule supports auto-fix.
 72→    fn supports_fix(&self) -> bool {
 73→        false
 74→    }
 75→}
