  1→//! App name format validation.
  2→//!
  3→//! This rule validates the format and conventions of the app_name field.
  4→
  5→use crate::config::BivvyConfig;
  6→use crate::lint::{LintDiagnostic, LintRule, RuleId, Severity};
  7→
  8→/// Validates app_name format and conventions.
  9→pub struct AppNameRule;
 10→
 11→impl LintRule for AppNameRule {
 12→    fn id(&self) -> RuleId {
 13→        RuleId::new("app-name-format")
 14→    }
 15→
 16→    fn name(&self) -> &str {
 17→        "App Name Format"
 18→    }
 19→
 20→    fn description(&self) -> &str {
 21→        "Validates app_name follows naming conventions"
 22→    }
 23→
 24→    fn default_severity(&self) -> Severity {
 25→        Severity::Warning
 26→    }
 27→
 28→    fn check(&self, config: &BivvyConfig) -> Vec<LintDiagnostic> {
 29→        let mut diagnostics = Vec::new();
 30→
 31→        if let Some(ref name) = config.app_name {
 32→            if name.is_empty() {
 33→                diagnostics.push(LintDiagnostic::new(
 34→                    self.id(),
 35→                    Severity::Error,
 36→                    "app_name cannot be empty",
 37→                ));
 38→            } else if name.contains(' ') {
 39→                diagnostics.push(
 40→                    LintDiagnostic::new(
 41→                        self.id(),
 42→                        self.default_severity(),
 43→                        "app_name contains spaces; consider using kebab-case",
 44→                    )
 45→                    .with_suggestion(format!(
 46→                        "Use \"{}\" instead",
 47→                        name.to_lowercase().replace(' ', "-")
 48→                    )),
 49→                );
 50→            }
 51→        }
 52→
 53→        diagnostics
 54→    }
 55→
 56→    fn supports_fix(&self) -> bool {
 57→        true
 58→    }
 59→}
