//! GitHub Actions output formatter.
//!
//! Formats lint diagnostics as GitHub Actions workflow commands
//! (`::error::`, `::warning::`, `::notice::`) so they appear as
//! annotations in pull requests and the Actions log.

use super::LintFormatter;
use crate::lint::{LintDiagnostic, Severity};
use std::io::Write;

/// Formats lint output as GitHub Actions workflow commands.
pub struct GithubActionsFormatter;

impl GithubActionsFormatter {
    pub fn new() -> Self {
        Self
    }

    fn command_name(severity: Severity) -> &'static str {
        match severity {
            Severity::Error => "error",
            Severity::Warning => "warning",
            Severity::Hint => "notice",
        }
    }
}

impl LintFormatter for GithubActionsFormatter {
    fn format<W: Write>(
        &self,
        diagnostics: &[LintDiagnostic],
        writer: &mut W,
    ) -> std::io::Result<()> {
        for diag in diagnostics {
            let cmd = Self::command_name(diag.severity);

            // Build the properties string (file, line, col, etc.)
            let mut props = Vec::new();

            if let Some(ref span) = diag.span {
                props.push(format!("file={}", span.file.display()));
                props.push(format!("line={}", span.start_line));
                props.push(format!("col={}", span.start_col));
                if span.end_line != span.start_line {
                    props.push(format!("endLine={}", span.end_line));
                }
                if span.end_col != usize::MAX {
                    props.push(format!("endColumn={}", span.end_col));
                }
            }

            props.push(format!("title={}", diag.rule_id));

            let props_str = props.join(",");

            // Append suggestion to the message if present
            let message = match &diag.suggestion {
                Some(suggestion) => format!("{} (help: {})", diag.message, suggestion),
                None => diag.message.clone(),
            };

            writeln!(writer, "::{cmd} {props_str}::{message}")?;
        }

        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::lint::{RuleId, Span};

    #[test]
    fn formats_error_annotation() {
        let formatter = GithubActionsFormatter::new();
        let diagnostics = vec![LintDiagnostic::new(
            RuleId::new("test-rule"),
            Severity::Error,
            "Something is wrong",
        )
        .with_span(Span::line("config.yml", 10))];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert_eq!(
            output,
            "::error file=config.yml,line=10,col=1,title=test-rule::Something is wrong\n"
        );
    }

    #[test]
    fn formats_warning_annotation() {
        let formatter = GithubActionsFormatter::new();
        let diagnostics = vec![LintDiagnostic::new(
            RuleId::new("test-rule"),
            Severity::Warning,
            "This might be a problem",
        )];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert_eq!(
            output,
            "::warning title=test-rule::This might be a problem\n"
        );
    }

    #[test]
    fn formats_hint_as_notice() {
        let formatter = GithubActionsFormatter::new();
        let diagnostics = vec![LintDiagnostic::new(
            RuleId::new("test-rule"),
            Severity::Hint,
            "Consider this",
        )];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert!(output.starts_with("::notice "));
    }

    #[test]
    fn includes_suggestion_in_message() {
        let formatter = GithubActionsFormatter::new();
        let diagnostics = vec![LintDiagnostic::new(
            RuleId::new("test-rule"),
            Severity::Warning,
            "Bad name",
        )
        .with_suggestion("Use kebab-case")];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert!(output.contains("Bad name (help: Use kebab-case)"));
    }

    #[test]
    fn includes_multiline_span_properties() {
        let formatter = GithubActionsFormatter::new();
        let diagnostics = vec![LintDiagnostic::new(
            RuleId::new("test-rule"),
            Severity::Error,
            "Multiline issue",
        )
        .with_span(Span::new("config.yml", 5, 3, 8, 15))];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert_eq!(
            output,
            "::error file=config.yml,line=5,col=3,endLine=8,endColumn=15,title=test-rule::Multiline issue\n"
        );
    }

    #[test]
    fn formats_multiple_diagnostics() {
        let formatter = GithubActionsFormatter::new();
        let diagnostics = vec![
            LintDiagnostic::new(RuleId::new("r1"), Severity::Error, "err"),
            LintDiagnostic::new(RuleId::new("r2"), Severity::Warning, "warn"),
        ];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        let lines: Vec<&str> = output.lines().collect();
        assert_eq!(lines.len(), 2);
        assert!(lines[0].starts_with("::error "));
        assert!(lines[1].starts_with("::warning "));
    }

    #[test]
    fn empty_diagnostics_produces_no_output() {
        let formatter = GithubActionsFormatter::new();
        let diagnostics: Vec<LintDiagnostic> = vec![];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();

        assert!(output.is_empty());
    }
}

